import {mount,unmount,flushSync} from "svelte";
import {act,createElement as h,type ComponentType} from "react";
import {createRoot} from "react-dom/client";
import {renderToString} from "react-dom/server";
import {afterEach,describe,expect,it,vi} from "vitest";
import * as react from "../react/src";
import Fixture from "./fixtures/FrameworkData.svelte";
import type {TerminalEngine,TerminalEngineOptions} from "../src/terminal-session";
Object.assign(globalThis,{IS_REACT_ACT_ENVIRONMENT:true});
const disposals:(()=>Promise<void>)[]=[];
afterEach(async()=>{while(disposals.length)await disposals.pop()!();vi.unstubAllGlobals();});
const datasets=[{id:"ok",label:"Success",data:[{x:0,y:80},{x:1,y:100},{x:2,y:90}]},{id:"failed",label:"Failures",data:[{x:0,y:20},{x:2,y:10}]}];
const defaults={
 CodeField:{label:"Template",value:undefined,suggestions:[{value:"user.blocked",disabled:true},{value:"user.name",label:"User name"},{value:"user.id",label:"User id"}],resolved:["user.name"],help:"Use a variable",name:"template"},
 Table:{caption:"Requests",columns:[{key:"id",header:"ID"},{key:"duration",header:"Duration",sortable:true,editable:true},{key:"region",header:"Region",filterable:true}],rows:[{id:"slow",duration:90,region:"sao"},{id:"fast",duration:10,region:"fra"},{id:"mid",duration:50,region:"sao"}],rowKey:"id",editable:true,pageSize:2},
 Graph:{label:"Request topology",renderer:"svg",data:{nodes:[{id:"api",label:"API",community:"request",metadata:{kind:"entry"}},{id:"db",label:"Database",community:"storage"}],edges:[{id:"query",source:"api",target:"db",label:"Query"}]},showDetails:true},
 MetricChart:{label:"Request throughput",data:datasets,variant:"stacked-area"},
 Sparkline:{label:"Trend",values:[0,5,-2,8],width:220,height:48},
 TimeSeries:{label:"Requests",data:datasets,width:640,height:240,variant:"stacked-area"},
 Histogram:{label:"Durations",values:[0,1,1,2,4,NaN,Infinity],bins:3,width:320,height:160},
 Heatmap:{label:"Activity",start:new Date(2026,9,1),end:new Date(2026,9,8),data:[{date:new Date(2026,9,1),value:3},{date:new Date(2026,9,1),value:2},{date:new Date(2026,9,2),value:10}],width:320,height:160},
 DocumentViewer:{label:"Documents",documents:[{id:"one",title:"First",body:"Request body"},{id:"two",title:"Second",body:"Response body"}]},
 TreeView:{label:"Files",nodes:[{id:"src",label:"Source",children:[{id:"api",label:"API",children:[]}]},{id:"test",label:"Tests",children:[]}]},
 JsonTree:{value:{status:200,nested:{value:"<script>text</script>"}},label:"JSON response"},
 XmlTree:{value:"<response><status>200</status><nested>content</nested></response>",label:"XML response"},
 VirtualList:{label:"Request list",rowKey:(item:string)=>item,items:Array.from({length:100},(_,i)=>`Request ${i}`),visibleRows:3,overscan:1},
 PanZoomViewport:{label:"Topology viewport",contentWidth:800,contentHeight:400,view:{x:0,y:0,scale:1}},
 TerminalSession:{label:"Request shell",engine:()=>liveEngine(),transcript:"<script>caller text</script>"},
 GeoMap:{label:"Regions",points:[{id:"sao",label:"São Paulo",latitude:-23.5,longitude:-46.6},{id:"fra",label:"Frankfurt",latitude:50.1,longitude:8.7}],routes:[{id:"replication",source:"sao",target:"fra",label:"Replication"}]},
} satisfies Record<string,Record<string,any>>;
type Name=keyof typeof defaults;type Flavor="svelte"|"react";
function liveEngine():TerminalEngine{return{write:vi.fn(),clear:vi.fn(),focus:vi.fn(),fit:vi.fn(),update:vi.fn(),dispose:vi.fn()};}
async function action(callback:()=>void){await act(async()=>{callback();flushSync();await Promise.resolve();flushSync();});}
const press=(node:Element,key:string)=>node.dispatchEvent(new KeyboardEvent("keydown",{key,bubbles:true,cancelable:true}));
function input(node:HTMLInputElement|HTMLTextAreaElement,value:string){Object.getOwnPropertyDescriptor(node instanceof HTMLTextAreaElement?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,"value")!.set!.call(node,value);node.dispatchEvent(new Event("input",{bubbles:true}));}
async function render(name:Name,flavor:Flavor,extra:Record<string,any>={}){
 const target=document.createElement("div");document.body.append(target);let options:Record<string,any>={...defaults[name],...extra};
 const native=()=>Object.fromEntries(Object.entries(options).map(([key,value])=>[key.startsWith("on")?key.toLowerCase():key,value]));
 if(flavor==="svelte"){const instance=mount(Fixture,{target,props:{name,options:native()}});flushSync();disposals.push(async()=>{await unmount(instance);target.remove();});return{target,update:async(next:Record<string,any>)=>{options={...options,...next};await action(()=>instance.update(native()));}};}
 const root=createRoot(target),element=()=>{let props={...options};if(name==="VirtualList")props.children=(item:unknown,index:number)=>h("button",{type:"button"},`${index}: ${String(item)}`);if(name==="PanZoomViewport")props.children=h("button",{type:"button"},"Inspect node");if(name==="Table")props.actions=(context:any)=>h("div",null,h("button",{type:"button",onClick:()=>options.action?.(context)},`Export ${context.rows.length} rows`),h("details",null,h("summary",null,"More actions"),h("button",{type:"button"},"Inspect selection")));return h(react[name] as ComponentType<any>,props);};await act(()=>root.render(element()));disposals.push(async()=>{await act(()=>root.unmount());target.remove();});return{target,update:async(next:Record<string,any>)=>{options={...options,...next};await act(()=>root.render(element()));}};
}
for(const name of Object.keys(defaults) as Name[])it(`${name} preserves native SSR and keeps appearance caller-owned`,()=>{const options:Record<string,any>={...defaults[name]};if(name==="VirtualList")options.children=(item:unknown)=>h("span",null,String(item));if(name==="PanZoomViewport")options.children=h("button",null,"Inspect node");const html=renderToString(h(react[name] as ComponentType<any>,options));expect(html.length).toBeGreaterThan(150);expect(html).not.toMatch(/data-(theme|color-scheme|density)=/);expect(html).not.toContain("<script>caller text</script>");if(["Sparkline","TimeSeries","Histogram","Heatmap"].includes(name)){expect(html).toContain("data-chart-placeholder");expect(html).not.toContain("<svg");}});
for(const flavor of ["svelte","react"] as const)describe(`${flavor} data contracts`,()=>{
 it("completes code variables, skips disabled suggestions and retains caret/form semantics",async()=>{
  const changed=vi.fn(),r=await render("CodeField",flavor,{onValueChange:changed}),editor=r.target.querySelector<HTMLInputElement>("[data-code-input]")!;
  await action(()=>{input(editor,"Hello {{us");editor.focus();editor.setSelectionRange(editor.value.length,editor.value.length);editor.click();});expect(editor.getAttribute("aria-expanded")).toBe("true");await action(()=>press(editor,"ArrowDown"));expect(document.getElementById(editor.getAttribute("aria-activedescendant")!)?.textContent).toBe("User name");await action(()=>press(editor,"Enter"));expect(changed).toHaveBeenLastCalledWith("Hello {{user.name}}");expect(editor.value).toBe("Hello {{user.name}}");expect(editor.selectionStart).toBe(editor.value.length);expect(document.activeElement).toBe(editor);expect(r.target.querySelector("[data-token-state=resolved]")?.textContent).toBe("{{user.name}}");const form=document.createElement("form");r.target.append(form);form.append(editor);expect(new FormData(form).get("template")).toBe("Hello {{user.name}}");
 });
 it("closes completion when disabled and keeps multiline native textbox semantics",async()=>{const r=await render("CodeField",flavor,{gutter:true}),editor=r.target.querySelector<HTMLTextAreaElement>("textarea")!;await action(()=>{input(editor,"{{us");editor.focus();editor.setSelectionRange(4,4);editor.click();});expect(r.target.querySelector('[role="listbox"]')).toBeTruthy();expect(editor.hasAttribute("role")).toBe(false);await r.update({disabled:true});expect(r.target.querySelector('[role="listbox"]')).toBeNull();expect(editor.disabled).toBe(true);});
 it("sorts, filters, pages and gives custom toolbar actions the transformed rows",async()=>{const exported=vi.fn(),r=await render("Table",flavor,{action:exported}),button=(label:string)=>[...r.target.querySelectorAll("button")].find(b=>b.textContent?.trim()===label)!;await action(()=>button("Duration").click());expect(r.target.querySelector("[data-table-cell]")?.textContent).toBe("fast");expect(r.target.querySelector('th[aria-sort="ascending"]')?.textContent).toBe("Duration");await action(()=>button("Next").click());expect(r.target.textContent).toContain("Page 2 of 2");await action(()=>input(r.target.querySelector('input[type=search]')!,"sao"));expect(r.target.querySelectorAll("[data-table-row]")).toHaveLength(2);await action(()=>button("Export 2 rows").click());expect(exported).toHaveBeenCalledWith(expect.objectContaining({rows:[defaults.Table.rows[2],defaults.Table.rows[0]]}));expect(r.target.querySelector("summary")?.textContent).toBe("Column visibility");expect([...r.target.querySelectorAll("summary")].some(s=>s.textContent==="More actions")).toBe(true);});
 it("edits once across Enter and blur, cancels Escape and preserves caller rows",async()=>{const changed=vi.fn(),r=await render("Table",flavor,{onChangesChange:changed}),cell=r.target.querySelector<HTMLElement>('[data-cell-row="0"][data-cell-column="1"]')!;await action(()=>{cell.focus();press(cell,"F2");});const editor=r.target.querySelector<HTMLInputElement>("[data-table-editor]")!;expect(document.activeElement).toBe(editor);await action(()=>editor.click());expect(document.activeElement).toBe(editor);await action(()=>input(editor,"110"));await action(()=>press(editor,"Enter"));expect(changed).toHaveBeenCalledTimes(1);expect(changed).toHaveBeenCalledWith([{rowKey:"slow",columnKey:"duration",previous:90,value:110}]);expect(defaults.Table.rows[0].duration).toBe(90);await action(()=>press(cell,"F2"));await action(()=>{input(r.target.querySelector('[data-table-editor]')!,"99");});await action(()=>press(r.target.querySelector('[data-table-editor]')!,"Escape"));expect(changed).toHaveBeenCalledTimes(1);expect(r.target.querySelector("[data-table-pending]")?.textContent).toBe("110");});
 it("keeps chart loading deferred until visibility and preserves fixed geometry",async()=>{let observe!:IntersectionObserverCallback;vi.stubGlobal("IntersectionObserver",class{constructor(callback:IntersectionObserverCallback){observe=callback;}observe(){}disconnect(){}unobserve(){}});const r=await render("Sparkline",flavor);expect(r.target.querySelector("[data-chart-placeholder]")?.getAttribute("style")).toContain("48px");expect(r.target.querySelector("svg")).toBeNull();await action(()=>observe([{isIntersecting:true}] as IntersectionObserverEntry[],{} as IntersectionObserver));await vi.waitFor(async()=>{await action(()=>{});expect(r.target.querySelector("[data-chart-loaded] svg")).toBeTruthy();},{timeout:15000});expect(r.target.querySelector('svg')?.getAttribute("height")).toBe("48");});
 it("shares exact readings, missing samples and controlled legend state",async()=>{const changed=vi.fn(),r=await render("TimeSeries",flavor,{onHiddenSeriesChange:changed,hiddenSeries:[]}),explorer=r.target.querySelector('[data-chart-explorer]')!;await action(()=>press(explorer,"Home"));expect(explorer.getAttribute("aria-valuetext")).toContain("Success: 80");await action(()=>press(explorer,"ArrowRight"));expect(explorer.getAttribute("aria-valuetext")).toContain("Failures: No sample");await action(()=>r.target.querySelector<HTMLButtonElement>('[data-chart-legend-item=failed]')!.click());expect(changed).toHaveBeenCalledWith(["failed"]);if(flavor==="react")expect(r.target.querySelector('[data-chart-legend-item=failed]')?.getAttribute("aria-pressed")).toBe("true");await r.update({hiddenSeries:["failed"]});expect(r.target.querySelector('[data-chart-legend-item=failed]')?.getAttribute("aria-pressed")).toBe("false");});
 for(const name of ["Histogram","Heatmap"] as const)it(`loads ${name} at its component boundary and retains accessible name`,async()=>{const r=await render(name,flavor,{loading:"eager"});await vi.waitFor(async()=>{await action(()=>{});expect(r.target.querySelector("[data-chart-loaded] svg")).toBeTruthy();},{timeout:15000});expect(r.target.querySelector("figure")?.getAttribute("aria-label")).toBe(defaults[name].label);expect(r.target.querySelectorAll("svg rect").length).toBeGreaterThan(1);});
 it("keeps metric headline independent of legend visibility and expands the same data",async()=>{const expanded=vi.fn(),r=await render("MetricChart",flavor,{onExpandedChange:expanded});expect(r.target.querySelector("[data-metric-value]")?.textContent).toBe("300");await action(()=>r.target.querySelector<HTMLButtonElement>('[data-metric-series=ok]')!.click());expect(r.target.querySelector("[data-metric-value]")?.textContent).toBe("300");await action(()=>r.target.querySelector<HTMLButtonElement>('[aria-label="Expand Request throughput"]')!.click());expect(expanded).toHaveBeenCalledWith(true);expect(r.target.querySelector("[data-metric-detail] table caption")?.textContent).toContain("observed sample statistics");expect(r.target.querySelector('[data-metric-detail] [data-chart-legend-item=ok]')?.getAttribute("aria-pressed")).toBe("false");});
 it("searches graph nodes and emits caller metadata through keyboard activation",async()=>{const focused=vi.fn(),interacted=vi.fn(),r=await render("Graph",flavor,{onFocusedNodeChange:focused,onInteraction:interacted});await action(()=>input(r.target.querySelector('input[type=search]')!,"api"));expect(r.target.querySelector("[data-graph-search-results]")?.textContent).toContain("API");expect(r.target.querySelector("[data-graph-search-results]")?.textContent).not.toContain("Database");const node=r.target.querySelector('[data-node-id="api"]')!;await action(()=>press(node,"Enter"));expect(focused).toHaveBeenCalledWith("api");expect(interacted).toHaveBeenCalledWith({kind:"node",action:"click",id:"api",metadata:{kind:"entry"}});expect(r.target.querySelector('[data-graph-details]')?.textContent).toContain("entry");expect(r.target.querySelector('[data-ds-graph]')?.getAttribute("data-engine-state")).toBe("fallback");});
 it("filters documents without changing ids and switches native detail modes",async()=>{const selected=vi.fn(),r=await render("DocumentViewer",flavor,{onSelect:selected});await action(()=>input(r.target.querySelector('input[type=search]')!,"Second"));const option=r.target.querySelector<HTMLButtonElement>('[role=option]')!;await action(()=>option.click());expect(selected).toHaveBeenCalledWith(defaults.DocumentViewer.documents[1],1);expect(r.target.querySelector("[data-document-body]")?.textContent).toBe("Response body");const raw=[...r.target.querySelectorAll<HTMLButtonElement>('[role=tab]')].find(b=>b.textContent?.trim()==="Raw")!;await action(()=>raw.click());expect(r.target.querySelector("[data-document-raw]")?.textContent).toContain('"id": "two"');});
 it("expands tree by keyboard, renames once and retains editor focus on pointer",async()=>{const renamed=vi.fn(),r=await render("TreeView",flavor,{onRename:renamed}),root=r.target.querySelector<HTMLElement>('[data-tree-id=src]')!;await action(()=>{root.focus();press(root,"ArrowRight");});expect(r.target.querySelector('[data-tree-id=api]')).toBeTruthy();await action(()=>press(root,"F2"));const editor=r.target.querySelector<HTMLInputElement>("[data-tree-rename]")!;await action(()=>editor.click());expect(document.activeElement).toBe(editor);await action(()=>input(editor,"Renamed source"));await action(()=>press(editor,"Enter"));expect(renamed).toHaveBeenCalledTimes(1);expect(renamed).toHaveBeenCalledWith(defaults.TreeView.nodes[0],"Renamed source");});
 for(const name of ["JsonTree","XmlTree"] as const)it(`${name} preserves expandable hierarchy and literal content`,async()=>{const r=await render(name,flavor);expect(r.target.querySelector('[role=tree]')).toBeTruthy();expect(r.target.querySelector("script")).toBeNull();const row=r.target.querySelector<HTMLElement>('[role=treeitem]')!;await action(()=>{row.focus();press(row,"ArrowRight");});expect(r.target.textContent).toContain("status");});
 it("bounds virtual rows, scrolls to later items and pins a focused offscreen control",async()=>{const r=await render("VirtualList",flavor),region=r.target.querySelector<HTMLElement>('[data-virtual-list]')!,first=r.target.querySelector<HTMLButtonElement>("button")!;expect(r.target.querySelectorAll('[data-virtual-key]').length).toBeLessThan(10);await action(()=>first.focus());await action(()=>{region.scrollTop=1200;region.dispatchEvent(new Event("scroll"));});expect(r.target.textContent).toContain("Request 18");expect(first.isConnected).toBe(true);expect(document.activeElement).toBe(first);});
 it("exposes zoom without intercepting interactive children",async()=>{const changed=vi.fn(),r=await render("PanZoomViewport",flavor,{view:undefined,onViewChange:changed}),viewport=r.target.querySelector<HTMLElement>('[aria-label="Topology viewport"]')!;await action(()=>press(viewport,"+"));expect(changed).toHaveBeenLastCalledWith(expect.objectContaining({scale:1.2}));const child=[...r.target.querySelectorAll("button")].find(b=>b.textContent==="Inspect node")!;await action(()=>press(child,"+"));expect(changed).toHaveBeenCalledTimes(1);});
 it("forwards terminal transport and disposes replaced engines while suppressing stale input",async()=>{let options!:TerminalEngineOptions;const first=liveEngine(),second=liveEngine(),session=vi.fn(),interaction=vi.fn(),r=await render("TerminalSession",flavor,{loading:"eager",engine:(_host:HTMLElement,next:TerminalEngineOptions)=>{options=next;return first;},onSessionChange:session,onInteraction:interaction});await action(()=>{});expect(session).toHaveBeenCalledWith(first);const old=options;await action(()=>{options.input("status\r");options.resize(80,24);options.resize(0,NaN);});expect(interaction).toHaveBeenCalledTimes(2);expect(first.write).not.toHaveBeenCalled();await r.update({readOnly:true});await action(()=>options.input("blocked"));expect(interaction).toHaveBeenCalledTimes(2);await r.update({engine:()=>second});expect(old.signal.aborted).toBe(true);expect(first.dispose).toHaveBeenCalledTimes(1);expect(session).toHaveBeenCalledWith(null);expect(session).toHaveBeenLastCalledWith(second);await action(()=>old.input("stale"));expect(interaction).toHaveBeenCalledTimes(2);expect(r.target.querySelector("script")).toBeNull();});
 it("keeps map points and routes available without any external geography or tile service",async()=>{const changed=vi.fn(),r=await render("GeoMap",flavor,{onSelectedChange:changed}),point=r.target.querySelector<HTMLElement>('[data-mark-id=sao]');expect(point).toBeTruthy();await action(()=>press(point!,"Enter"));expect(changed).toHaveBeenCalledWith("sao");expect(r.target.textContent).toContain("Replication");});
});
